const HelpCoreEntry *help_core_get_db(int *size)
{
    if (size) {
        int count = 0;
        while (help_db[count].keyword != NULL) {
            count++;
        }
        *size = count;
    }
    return help_db;
}

const char *help_core_get_category_name(int cat_id)
{
    if (cat_id < 0 || cat_id >= HCAT_CORE_COUNT) return "Unknown";
    return help_cat_names[cat_id];
}
